/* v8 · 存量包自愈：v7 的空 nav 补丁把抽屉 .sheet-item 的 SVG 图标与 <b>/<small>
   压成纯文本，并让 6 个校园服务共用一份缓存变成同名。这里按静态映射重建，
   并把危险的两个热更函数换成安全实现。v8 自身不带 nav/text 字段，不再触发破坏。 */
(function (w, d) {
  var ROUTE = {
    xk:["xk","选课"], bk:["bk","本学期课程"], py:["py","培养计划"],
    wc:["wc","完成情况"], ks:["ks","考试安排"], cet:["cet","四六级"],
    gr:["gr","个人信息"], diag:["diag","诊断"], dm:["dm","免责声明"],
    set:["set","设置"], report:["cj","学期报告"], timeline:["calendar","时间轴"],
    others:["shield","其他功能"], links:["wx","快速入口"]
  };
  var WX = {
    "i-HBUT":["wx","i湖工","微信服务号"],
    "gh_ab64209e39f2":["shield","平安湖工大","微信服务号"],
    "hggchq":["wx","湖工工程后勤","设备维修"],
    "gc-xszzfzzx":["wx","工程学声","公众号"]
  };
  function urlRow(u){
    if (u.indexOf("syyxxzx") >= 0) return ["shield","实验与信息中心","校园网 / 网络报修"];
    if (u.indexOf("czrxdzonline") >= 0 || u.indexOf("pay.") >= 0)
      return ["bulb","照明线路缴费","校园网页 · 在线缴费"];
    return null;
  }
  /* 安全版：只改 <b>/文字 span，绝不整容器 textContent，也不用 route 做共享 key */
  function patchBadImpl(){
    try {
      var navSrc = String(w.applyHotNav || ""), txtSrc = String(w.applyHotText || "");
      var badNav = navSrc.indexOf('span:last-child') >= 0 && navSrc.indexOf('|| it') >= 0;
      var badTxt = txtSrc.indexOf('el.textContent = val') >= 0;
      if (badNav) {
        w.applyHotNav = function (nav) {
          if (!nav || typeof nav !== "object" || !Object.keys(nav).length) return;
          var hide = nav.hide || [], dis = nav.disabled || [], ren = nav.rename || {};
          w.__zkDisabled = new Set(dis);
          ["#nav .nav-item", "#tabbar .tab", ".sheet-item"].forEach(function (sel) {
            [].slice.call(d.querySelectorAll(sel)).forEach(function (it) {
              var r = it.getAttribute("data-route") || "";
              var h = r && (hide.indexOf(r) >= 0 || dis.indexOf(r) >= 0);
              it.style.display = h ? "none" : "";
              it.classList.toggle("zk-disabled", !!(r && dis.indexOf(r) >= 0));
              var lab = it.querySelector("b") || it.querySelector("span:not(.ni)");
              if (lab && r && ren[r] != null) lab.textContent = String(ren[r]);
            });
          });
        };
      }
      if (badTxt) {
        w.applyHotText = function (map) {
          if (!map || typeof map !== "object" || !Object.keys(map).length) return;
          Object.keys(map).forEach(function (sel) {
            try {
              [].slice.call(d.querySelectorAll(sel)).forEach(function (el) {
                var lab = el.querySelector("b") || el.querySelector("span:not(.ni)");
                var t = (el.children.length && lab) ? lab : el;
                t.textContent = String(map[sel] == null ? "" : map[sel]);
              });
            } catch (e) {}
          });
        };
      }
    } catch (e) {}
  }
  function heal(){
    /* 无论图标当前是否完好，先按特征把存量包里的坏实现换掉，避免以后再被空 nav 破坏。
       新版 fix2 的实现不含这两个特征，不会被覆盖，order/rename 能力完整保留。 */
    patchBadImpl();
    var items = d.querySelectorAll(".sheet-item"), broken = 0, i;
    for (i = 0; i < items.length; i++)
      if (!items[i].querySelector(".ni[data-ico]")) broken++;
    if (!broken) return;               // 图标完好（新包 / 已自愈）：只换实现，不动 DOM
    for (i = 0; i < items.length; i++){
      var el = items[i], row = null,
          r  = el.getAttribute("data-route"),
          wx = el.getAttribute("data-wx"),
          u  = el.getAttribute("data-url") || "";
      if (r && ROUTE[r]) row = ROUTE[r];
      else if (wx && WX[wx]) row = WX[wx];
      else if (u) row = urlRow(u);
      if (!row) continue;
      el.innerHTML = '<span class="ni" data-ico="' + row[0] + '"></span><b>' + row[1] + '</b>' +
                     (row[2] ? '<small>' + row[2] + '</small>' : '');
    }
    if (typeof w.injectIcons === "function") { try { w.injectIcons(); } catch (e) {} }
  }
  try { heal(); } catch (e) {}

  /* 存量包的应用内下载卡片把「浏览器下载 / 备用页」一起禁用了，用户被锁死在 0%。
     做幂等解锁守卫：这两个按钮一出现且被禁用就放开；新包本就未禁用，无副作用。 */
  try {
    if (!w.__zkUpdUnlock) {
      w.__zkUpdUnlock = 1;
      setInterval(function () {
        var alt = d.getElementById('upd-alt'), fb = d.getElementById('upd-fb');
        if (alt && alt.disabled) alt.disabled = false;
        if (fb && fb.disabled) fb.disabled = false;
      }, 600);
    }
  } catch (e) {}

  /* 老包（无多源下载桥）沿用 v7 的更新入口防护：改道浏览器下载页。
     带 apkUpdateMulti 的新包不受干预，由源码走应用内多源下载。 */
  var N = w.ZhikeNative;
  var legacy = !N || typeof N.apkUpdateMulti !== "function";
  if (!legacy) return;
  var URL = "https://1855215134.share.123pan.cn/123pan/lmaCvd-nid8h?pwd=f3sa#";
  var PW  = "f3sa", last = 0;
  function open() {
    var now = Date.now();
    if (now - last < 800) return;
    last = now;
    if (N && typeof N.openDownloadPage === "function") {
      try { N.openDownloadPage(URL, PW); return; } catch (e) {}
    }
    if (N && typeof N.openUrl === "function") {
      try { N.openUrl(URL); return; } catch (e) {}
    }
    try { w.open(URL, "_blank", "noopener,noreferrer"); } catch (e) {}
  }
  w.canInAppDownload = function(){ return false; };
  w.checkUpdate = open; w.startApkUpdate = open;
  w.openDownloadLegacy = open; w.showUpdSheet = open;
  if (!w.__zkUpdHotV7) {           /* 复用 v7 标记，避免重复注册两套点击监听 */
    w.__zkUpdHotV7 = 1;
    w.addEventListener("click", function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      if (t.closest("#zk-upgrade, #btn-check-update, [data-zk='check-update']")) {
        e.preventDefault(); e.stopImmediatePropagation(); open();
      }
    }, true);
  }
})(window, document);
